import java.util.Arrays;
import java.util.Scanner;

public class LuckyTickets {
    private static final int MOD = 998244353;
    private static final int ROOT = 15311432;
    private static final int INVROOT = 469870224;

    private static int bitReverse(int n, int k) {
        return Integer.reverse(n) >>> (32 - k);
    }

    private static long inverseMod(int a) {
        return powMod(a, MOD - 2);
    }

    private static long powMod(int a, int p) {
        if (p == 0) return 1;
        long half = powMod(a, p / 2);
        long res = (half * half) % MOD;
        if (p % 2 == 1) res = (res * a) % MOD;
        return res;
    }

    private static void fftTransform(long[] coef, int logN, boolean invert) {
        int baseRoot = invert ? INVROOT : ROOT;
        long root = powMod(baseRoot, (int) Math.pow(2, 23 - logN));
        long[] roots = new long[logN];
        roots[logN - 1] = root;
        for (int i = logN - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        for (int s = 0; s < logN; s++) {
            int len = 1 << s;
            for (int start = 0; start < coef.length; start += 2 * len) {
                long curRoot = 1;
                for (int j = start; j < start + len; j++) {
                    long t = (curRoot * coef[j + len]) % MOD;
                    long u = coef[j];
                    coef[j] = (u + t) % MOD;
                    coef[j + len] = (u - t) % MOD;
                    curRoot = (roots[s] * curRoot) % MOD;
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] nums = new int[m];
        for (int i = 0; i < m; i++) {
            nums[i] = sc.nextInt();
        }
        Arrays.sort(nums);
        int minSize = n * nums[m - 1] + 2;
        int k = 0;
        int size = 1;
        while (size < minSize) {
            size <<= 1;
            k++;
        }
        long[] a = new long[size];
        for (int num : nums) {
            a[bitReverse(num, k)] = 1;
        }
        fftTransform(a, k, false);
        for (int i = 0; i < size; i++) {
            a[i] = powMod((int) a[i], n);
        }
        long[] temp = new long[size];
        for (int i = 0; i < size; i++) {
            temp[bitReverse(i, k)] = a[i] % MOD;
        }
        a = temp;
        fftTransform(a, k, true);
        long sum = 0;
        for (int i = 0; i < size; i++) {
            sum = (sum + a[i] * a[i]) % MOD;
        }
        long invSize = inverseMod(size);
        System.out.println((((sum * invSize) % MOD) * invSize) % MOD);
    }
}
